// One-off (probe-go branch): runs the live dashboard's own collect() with the real keys (main = live-23, working tree = live-24), then
// independent GA4 / Search Console queries to check its numbers. Aggregates only, nothing personal.
import crypto from "node:crypto";
const env = { GA_SERVICE_ACCOUNT_JSON: process.env.GA_SERVICE_ACCOUNT_JSON, GA_PROPERTY_ID: process.env.GA_PROPERTY_ID || "557990379", CF_API_TOKEN: process.env.CF_API_TOKEN, CF_ACCOUNT_ID: process.env.CF_ACCOUNT_ID, PLAY_REPORTS_BUCKET: "pubsite_prod_4688106336294834537" };
console.log("at", new Date().toISOString(), "| CF token present:", !!env.CF_API_TOKEN, "| CF account present:", !!env.CF_ACCOUNT_ID);
const out = {};
for (const v of ["live23", "live24"]) {
  try { const m = await import(`./${v}.mjs`); const d = await m.collect(env); out[v] = d; console.log(`\n===== ${v} collect() =====\n` + JSON.stringify(d, null, 1).slice(0, 60000)); }
  catch (e) { console.log(`${v} collect failed: ${e.stack || e}`); }
}
// ---- independent queries ----
const sa = JSON.parse(env.GA_SERVICE_ACCOUNT_JSON), P = env.GA_PROPERTY_ID;
const b64 = o => Buffer.from(typeof o === "string" ? o : JSON.stringify(o)).toString("base64url"), now = Math.floor(Date.now() / 1000);
const un = b64({alg: "RS256", typ: "JWT"}) + "." + b64({iss: sa.client_email, scope: "https://www.googleapis.com/auth/analytics.readonly https://www.googleapis.com/auth/webmasters.readonly", aud: "https://oauth2.googleapis.com/token", iat: now, exp: now + 3600});
const jwt = un + "." + crypto.createSign("RSA-SHA256").update(un).sign(sa.private_key).toString("base64url");
const tok = (await (await fetch("https://oauth2.googleapis.com/token", {method: "POST", headers: {"content-type": "application/x-www-form-urlencoded"}, body: "grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer&assertion=" + jwt})).json()).access_token;
const call = async (kind, body) => { const r = await fetch(`https://analyticsdata.googleapis.com/v1beta/properties/${P}:${kind}`, {method: "POST", headers: {authorization: "Bearer " + tok, "content-type": "application/json"}, body: JSON.stringify(body)}); const j = await r.json(); if (!r.ok) { console.log("ERR", kind, JSON.stringify(j).slice(0, 300)); return []; } return j.rows || []; };
const show = (title, rows) => { console.log("\n## " + title); for (const r of rows || []) console.log((r.dimensionValues || []).map(x => x.value).join(" | ") + "  =>  " + r.metricValues.map(x => x.value).join(" / ")); };
const REAL = {orGroup: {expressions: [{filter: {fieldName: "platform", stringFilter: {value: "web"}}}, {filter: {fieldName: "countryId", stringFilter: {value: "IL"}}}]}};
const ev = v => ({filter: {fieldName: "eventName", stringFilter: {value: v}}}), evs = vs => ({filter: {fieldName: "eventName", inListFilter: {values: vs}}}), and = (...e) => ({andGroup: {expressions: e}});
const d = (s, e) => ({startDate: s, endDate: e});
const Wk = out.live23?.weekly?.W || ["7daysAgo", "yesterday"], Pk = out.live23?.weekly?.P || ["14daysAgo", "8daysAgo"];
console.log("\n\n===== independent checks; dashboard week W =", Wk, "P =", Pk);
show("I1 W: car_lookup by platform | country (events / users)", await call("runReport", {dateRanges: [d(...Wk)], dimensions: [{name: "platform"}, {name: "countryId"}], metrics: [{name: "eventCount"}, {name: "totalUsers"}], dimensionFilter: ev("car_lookup"), limit: 50}));
show("I1b P: car_lookup by platform | country", await call("runReport", {dateRanges: [d(...Pk)], dimensions: [{name: "platform"}, {name: "countryId"}], metrics: [{name: "eventCount"}, {name: "totalUsers"}], dimensionFilter: ev("car_lookup"), limit: 50}));
show("I2 W: car_lookup REAL by date", await call("runReport", {dateRanges: [d(...Wk)], dimensions: [{name: "date"}], metrics: [{name: "eventCount"}], dimensionFilter: and(ev("car_lookup"), REAL), orderBys: [{dimension: {dimensionName: "date"}}]}));
show("I3 W: car_lookup REAL by platform | kind", await call("runReport", {dateRanges: [d(...Wk)], dimensions: [{name: "platform"}, {name: "customEvent:kind"}], metrics: [{name: "eventCount"}], dimensionFilter: and(ev("car_lookup"), REAL)}));
show("I4 28d: every event by platform (REAL) events / users / per user", await call("runReport", {dateRanges: [d("28daysAgo", "yesterday")], dimensions: [{name: "platform"}, {name: "eventName"}], metrics: [{name: "eventCount"}, {name: "totalUsers"}, {name: "eventCountPerUser"}], dimensionFilter: REAL, limit: 200, orderBys: [{metric: {metricName: "eventCount"}, desc: true}]}));
show("I5 28d: Android every event by country (events)", await call("runReport", {dateRanges: [d("28daysAgo", "yesterday")], dimensions: [{name: "countryId"}, {name: "eventName"}], metrics: [{name: "eventCount"}, {name: "totalUsers"}], dimensionFilter: {filter: {fieldName: "platform", stringFilter: {value: "Android"}}}, limit: 200, orderBys: [{metric: {metricName: "eventCount"}, desc: true}]}));
show("I6 28d: link events by platform | event | kind | via", await call("runReport", {dateRanges: [d("28daysAgo", "today")], dimensions: [{name: "platform"}, {name: "eventName"}, {name: "customEvent:kind"}, {name: "customEvent:via"}], metrics: [{name: "eventCount"}], dimensionFilter: evs(["link_landing", "link_open", "referral_open", "web_hint_click", "web_install_click", "web_install_prompt"]), limit: 200}));
show("I7 28d: Android first_open by firstUserSource | medium | campaign | country", await call("runReport", {dateRanges: [d("28daysAgo", "today")], dimensions: [{name: "firstUserSource"}, {name: "firstUserMedium"}, {name: "firstUserCampaignName"}, {name: "countryId"}], metrics: [{name: "eventCount"}], dimensionFilter: and(ev("first_open"), {filter: {fieldName: "platform", stringFilter: {value: "Android"}}}), limit: 100}));
show("I8 today: link_landing by kind | via", await call("runReport", {dateRanges: [d("today", "today")], dimensions: [{name: "customEvent:kind"}, {name: "customEvent:via"}], metrics: [{name: "eventCount"}], dimensionFilter: ev("link_landing")}));
show("I8b today+yesterday: web events by date | hour (events)", await call("runReport", {dateRanges: [d("yesterday", "today")], dimensions: [{name: "dateHour"}, {name: "eventName"}], metrics: [{name: "eventCount"}], dimensionFilter: {filter: {fieldName: "platform", stringFilter: {value: "web"}}}, limit: 300, orderBys: [{dimension: {dimensionName: "dateHour"}}]}));
show("I9 realtime: users by platform", await call("runRealtimeReport", {dimensions: [{name: "platform"}], metrics: [{name: "activeUsers"}]}));
show("I9b realtime REAL: events", await call("runRealtimeReport", {dimensions: [{name: "eventName"}], metrics: [{name: "eventCount"}], dimensionFilter: REAL, limit: 40}));
show("I10 W: session_start / first_open / user_engagement Android by country", await call("runReport", {dateRanges: [d(...Wk)], dimensions: [{name: "countryId"}, {name: "eventName"}], metrics: [{name: "eventCount"}, {name: "totalUsers"}, {name: "newUsers"}, {name: "activeUsers"}], dimensionFilter: and(evs(["session_start", "first_open", "user_engagement", "app_remove", "app_update"]), {filter: {fieldName: "platform", stringFilter: {value: "Android"}}}), limit: 50}));
show("I11 28d: Android activeUsers / newUsers by country (no event filter)", await call("runReport", {dateRanges: [d("28daysAgo", "yesterday")], dimensions: [{name: "countryId"}], metrics: [{name: "activeUsers"}, {name: "newUsers"}, {name: "totalUsers"}], dimensionFilter: {filter: {fieldName: "platform", stringFilter: {value: "Android"}}}, limit: 50}));
show("I12 W: Android appVersion (active users, IL)", await call("runReport", {dateRanges: [d(...Wk)], dimensions: [{name: "appVersion"}], metrics: [{name: "activeUsers"}, {name: "eventCount"}], dimensionFilter: and({filter: {fieldName: "platform", stringFilter: {value: "Android"}}}, {filter: {fieldName: "countryId", stringFilter: {value: "IL"}}}), limit: 30}));
show("I13 28d: newsletter_confirm, b2b_lead_submit by platform (events)", await call("runReport", {dateRanges: [d("2026-10-01", "today")], dimensions: [{name: "platform"}, {name: "eventName"}], metrics: [{name: "eventCount"}], dimensionFilter: evs(["newsletter_confirm", "b2b_lead_submit"])}));
show("I14 W: share by platform | kind", await call("runReport", {dateRanges: [d(...Wk)], dimensions: [{name: "platform"}, {name: "customEvent:kind"}], metrics: [{name: "eventCount"}], dimensionFilter: and(ev("share"), REAL)}));
// Search Console, as an independent read
const sc = async body => { const r = await fetch("https://www.googleapis.com/webmasters/v3/sites/" + encodeURIComponent("sc-domain:luchit.app") + "/searchAnalytics/query", {method: "POST", headers: {authorization: "Bearer " + tok, "content-type": "application/json"}, body: JSON.stringify(body)}); const j = await r.json(); if (!r.ok) { console.log("SC ERR", JSON.stringify(j).slice(0, 300)); return []; } return j.rows || []; };
console.log("\n## SC by date (clicks / impressions / position), last 16 days");
for (const r of await sc({startDate: new Date(Date.now() - 16 * 864e5).toISOString().slice(0, 10), endDate: new Date().toISOString().slice(0, 10), dimensions: ["date"], dataState: "all"})) console.log(r.keys[0], r.clicks, r.impressions, r.position.toFixed(1));
